/* ============ 🧮 كشف حساب لزبون خاص (له/عليه) ============ */
let ledClient='', ledFrom='', ledTo='', ledCfgOpen=false, ledQ='';

/* تعديل بيانات الكشف من داخل الشاشة — متاح لكل مستخدم */
function saveLedCfg(){
  const ph=$('lgPhone'), ad=$('lgAddr'), cu=$('lgCur');
  if(ph) settings.phone=ph.value.trim();
  if(ad) settings.address=ad.value.trim();
  if(cu) settings.currency=cu.value.trim();
  saveSet(); ledCfgOpen=true; vLedger();
  notify('✅ انحفظت بيانات الكشف','ok');
}
function vLedger(){
  const all=ledgerClients();
  const q=key(ledQ);
  const list=all.filter(n=>{
    if(!q) return true;
    const r=clientRec(n)||{};
    return key(n+' '+(r.phone||'')+' '+(r.note||'')).includes(q);
  });
  if(ledClient && !all.includes(ledClient)) ledClient='';

  $('view').innerHTML=`
  <div class="card noprint">
    <h2>🧮 كشف حساب لزبونك الخاص</h2>
    <p class="hint">دفتر زبائنك الخاص — الحركات والكشوفات بتنحفظ لكل زبون لحاله.</p>
    <div class="row">
      <input id="ledSearch" placeholder="🔎 دوّر باسم الزبون أو رقمه…" value="${esc(ledQ)}"
        style="flex:1;min-width:190px"
        oninput="clearTimeout(window.__lq);window.__lq=setTimeout(()=>{ledQ=this.value;vLedger()},250)">
      <button class="btn" onclick="addLedClient()">+ زبون جديد</button>
    </div>
    ${all.length?`
    <div class="cliGrid">
      ${list.map(n=>{
        const r=clientRec(n)||{}, t=ledgerTotals(n);
        const on=(n===ledClient);
        return `<div class="cliCard ${on?'on':''}" onclick="pickClient('${esc(n).replace(/'/g,"\\'")}')">
          <div class="cliTop">
            <b>${esc(n)}</b>
            <span class="cliBal ${t.balance>0?'owe':t.balance<0?'cred':''}">${fx(Math.abs(t.balance))}</span>
          </div>
          <div class="cliMeta">
            ${r.phone?`📞 ${esc(r.phone)}`:'<span class="mut">بدون رقم</span>'}
            · ${t.count} حركة
            ${t.balance>0?'<span class="tagOwe">عليه</span>':t.balance<0?'<span class="tagCred">له</span>':'<span class="tagZero">مسدّد</span>'}
          </div>
          ${r.note?`<div class="cliNote">${esc(r.note)}</div>`:''}
          <div class="cliAct">
            <button class="btn sec sm" onclick="event.stopPropagation();editClient('${esc(n).replace(/'/g,"\\'")}')">تعديل</button>
            <button class="btn danger sm" onclick="event.stopPropagation();delClient('${esc(n).replace(/'/g,"\\'")}')">حذف</button>
          </div>
        </div>`;}).join('')||'<div class="mut" style="padding:10px">ما في نتائج للبحث</div>'}
    </div>`:'<div class="okbox" style="margin-top:10px">ما عندك زبائن بعد — اضغط «+ زبون جديد».</div>'}
  </div>

  ${ledClient?`
  <div class="card noprint">
    <h2>حركة جديدة — ${esc(ledClient)}</h2>
    <div class="grid g4">
      <div><label>التاريخ</label><input type="date" id="leD" value="${todayStr()}"></div>
      <div><label>البيان</label><input id="leX" placeholder="بضاعة / دفعة نقدية"></div>
      <div><label>عليه (مدين)</label><input id="leDeb" type="number" step="any" placeholder="0.000"></div>
      <div><label>له (دائن)</label><input id="leCre" type="number" step="any" placeholder="0.000"></div>
    </div>
    <div class="row" style="margin-top:12px">
      <button class="btn" onclick="addLedRow()">➕ أضف الحركة</button>
      <span class="hint" style="margin:0">«عليه» = بضاعة طلعتله · «له» = دفعة استلمتها منه</span>
    </div>
    <div class="grid g3" style="margin-top:12px">
      <div><label>من تاريخ</label><input type="date" value="${ledFrom}" onchange="ledFrom=this.value;drawLedger()"></div>
      <div><label>إلى تاريخ</label><input type="date" value="${ledTo}" onchange="ledTo=this.value;drawLedger()"></div>
      <div><label>&nbsp;</label><button class="btn sec" style="width:100%"
        onclick="ledFrom='';ledTo='';vLedger()">كل الفترات</button></div>
    </div>
    <details class="ledCfg" ${ledCfgOpen?'open':''} ontoggle="ledCfgOpen=this.open">
      <summary>⚙️ تعديل بيانات الكشف (الهاتف · العنوان · العملة)</summary>
      <div class="grid g3" style="margin-top:10px">
        <div><label>رقم الهاتف</label>
          <input id="lgPhone" value="${esc(settings.phone||'')}" placeholder="0798003050"></div>
        <div><label>العنوان</label>
          <input id="lgAddr" value="${esc(settings.address||'')}" placeholder="الأردن — عمان"></div>
        <div><label>العملة</label>
          <input id="lgCur" value="${esc(settings.currency||'')}" placeholder="دينار / د.أ"></div>
      </div>
      <div class="row" style="margin-top:10px">
        <button class="btn" onclick="saveLedCfg()">💾 حفظ</button>
        <span class="hint" style="margin:0">بتظهر بأسفل كشف الحساب وبملف الإكسل.</span>
      </div>
    </details>
  </div>`:''}
  <div id="ledBox"></div>`;
  drawLedger();
}

function pickClient(n){ ledClient=n; vLedger();
  setTimeout(()=>{ const b=$('ledBox'); if(b) try{b.scrollIntoView({behavior:'smooth'})}catch(e){} },60); }

async function addLedClient(){
  const ok=await ask({title:'زبون جديد',ok:'إضافة',
    body:`<label>اسم الزبون *</label><input id="__lc" class="mInput" placeholder="اسم المحل أو الشخص">
      <label style="margin-top:8px">رقم الهاتف</label><input id="__lp" class="mInput" placeholder="07…">
      <label style="margin-top:8px">ملاحظة</label><input id="__ln" class="mInput" placeholder="العنوان أو أي تفصيل">`});
  if(!ok) return;
  const V=(ok&&ok.vals)||{};
  const n=String(V.__lc||'').trim();
  if(!n){ notify('اكتب اسم الزبون','warn'); return; }
  if(ledgerClients().some(x=>key(x)===key(n))){ notify('الزبون موجود عندك','warn'); ledClient=n; return vLedger(); }
  lclients.push({id:uid(),owner:SESSION.user,name:n,
    phone:String(V.__lp||'').trim(),note:String(V.__ln||'').trim(),
    at:new Date().toISOString()});
  saveLClients(); ledClient=n; ledQ=''; vLedger();
  notify('✅ انضاف الزبون','ok');
}

async function editClient(name){
  const r=clientRec(name)||{name,phone:'',note:''};
  const ok=await ask({title:'تعديل بيانات الزبون',ok:'حفظ',
    body:`<label>اسم الزبون *</label><input id="__lc" class="mInput" value="${esc(r.name||name)}">
      <label style="margin-top:8px">رقم الهاتف</label><input id="__lp" class="mInput" value="${esc(r.phone||'')}">
      <label style="margin-top:8px">ملاحظة</label><input id="__ln" class="mInput" value="${esc(r.note||'')}">`});
  if(!ok) return;
  const V=(ok&&ok.vals)||{};
  const nn=String(V.__lc||'').trim();
  if(!nn){ notify('الاسم مطلوب','warn'); return; }
  if(key(nn)!==key(name) && ledgerClients().some(x=>key(x)===key(nn))){
    notify('في زبون ثاني بنفس الاسم','warn'); return; }
  let rec=clientRec(name);
  if(!rec){ rec={id:uid(),owner:SESSION.user,name,phone:'',note:'',at:new Date().toISOString()};
            lclients.push(rec); }
  rec.name=nn; rec.phone=String(V.__lp||'').trim(); rec.note=String(V.__ln||'').trim();
  /* لو الاسم تغيّر، نحدّث حركاته كمان */
  if(nn!==name){
    ledger.forEach(e=>{ if(String(e.owner).toLowerCase()===String(SESSION.user).toLowerCase()
        && e.client===name) e.client=nn; });
    saveLedger();
    if(ledClient===name) ledClient=nn;
  }
  saveLClients(); vLedger(); notify('✅ انحفظت التعديلات','ok');
}

async function delClient(name){
  const t=ledgerTotals(name);
  const ok=await ask({title:'حذف زبون',danger:true,ok:'احذف نهائيًا',
    requireText: t.count?'احذف':null,
    body:`<b>${esc(name)}</b><br><br>
      ${t.count?`⚠️ عنده <b>${t.count}</b> حركة مسجّلة ورصيد
        <b>${fx(Math.abs(t.balance))}</b> — رح تنمسح كل حركاته معه.<br>
        <span class="mut">اكتب «احذف» للتأكيد.</span>`
      :'ما عنده حركات مسجّلة.'}`});
  if(!ok) return;
  const me=String(SESSION.user).toLowerCase();
  const removedRows=ledger.filter(e=>String(e.owner).toLowerCase()===me && e.client===name);
  const removedRec=clientRec(name);
  ledger=ledger.filter(e=>!(String(e.owner).toLowerCase()===me && e.client===name));
  lclients=lclients.filter(c=>!(String(c.owner).toLowerCase()===me && c.name===name));
  saveLedger(); saveLClients();
  toTrash('lclient',`زبون ${name} (${removedRows.length} حركة)`,{rec:removedRec,rows:removedRows});
  if(ledClient===name) ledClient='';
  vLedger();
  const tid=trash[0].id;
  notify(`انحذف ${name}`,'warn',9000,()=>{ restoreTrash(tid); vLedger(); notify('رجع الزبون ✅','ok'); });
}

function addLedRow(){
  if(!ledClient){ notify('اختر زبون أولًا','warn'); return; }
  const dt=$('leD').value||todayStr();
  const dx=($('leX').value||'').trim();
  const db=parseFloat($('leDeb').value)||0;
  const cr=parseFloat($('leCre').value)||0;
  if(!db && !cr){ notify('احط مبلغ بخانة «عليه» أو «له»','warn'); return; }
  ledger.push({id:uid(),owner:SESSION.user,client:ledClient,date:dt,
    desc:dx||(db?'بضاعة':'دفعة'),debit:db,credit:cr,at:new Date().toISOString()});
  saveLedger();
  $('leX').value='';$('leDeb').value='';$('leCre').value='';
  drawLedger(); notify('✅ انضافت الحركة','ok');
}

async function delLedRow(id){
  const e=ledger.find(x=>x.id===id); if(!e) return;
  const ok=await ask({title:'حذف حركة',danger:true,ok:'احذف',
    body:`<b>${esc(e.desc)}</b> — ${esc(e.date)}<br>
      عليه ${fx(e.debit)} · له ${fx(e.credit)}`});
  if(!ok) return;
  ledger=ledger.filter(x=>x.id!==id); saveLedger(); drawLedger();
  notify('انحذفت الحركة','warn');
}

/* الفترة الفعلية: أول وآخر حركة ظاهرة */
function ledPeriod(){
  /* القيد الافتتاحي الصفري ما بيحدد الفترة */
  const R=ledView().filter(e=>(+e.debit||0)||(+e.credit||0));
  if(!R.length) return (ledFrom||ledTo) ? `${ledFrom||'—'} ← ${ledTo||'—'}` : '';
  const ds=R.map(e=>e.date).sort();
  return ds[0]===ds[ds.length-1] ? ds[0] : `${ds[0]} ← ${ds[ds.length-1]}`;
}

function ledView(){
  let R=ledgerRows(ledClient);
  if(ledFrom) R=R.filter(e=>e.date>=ledFrom);
  if(ledTo)   R=R.filter(e=>e.date<=ledTo);
  return R;
}

function drawLedger(){
  const box=$('ledBox'); if(!box) return;
  if(!ledClient){ box.innerHTML='<div class="card">أضف زبون عشان تبدأ كشف حسابه.</div>'; return; }
  const R=ledView();
  let run=0, deb=0, cre=0;
  const body=R.map((e,i)=>{
    const d=+e.debit||0, c=+e.credit||0;
    run+=d-c; deb+=d; cre+=c;
    return `<tr>
      <td>${i+1}</td><td class="lDate">${esc(e.date)}</td>
      <td class="name">${esc(e.desc)}</td>
      <td class="amt vOut">${d?fx(d):''}</td>
      <td class="amt vIn">${c?fx(c):''}</td>
      <td class="amt"><b>${fx(run)}</b></td>
      <td class="noprint"><button class="btn danger sm" onclick="delLedRow('${e.id}')">حذف</button></td>
    </tr>`;}).join('');
  const bal=deb-cre;
  box.innerHTML=`
  <div class="card ledSheet watermark">
    <div class="ledHead">
      <img class="ledLogo" src="${BADGE}" alt="ALMEFLEH">
      <div class="ledCo">
        <div class="coName">شركة عبد الرؤوف المفلح وأولاده</div>
        <div class="coSub">ALMEFLEH — منذ 1972</div>
      </div>
      <div class="ledTitle">كشف حساب</div>
    </div>
    <div class="ledTo">
      <div><span class="lbl">السادة المحترمين</span>
        <span class="lVal">${esc(ledClient)}</span>
        ${(clientRec(ledClient)||{}).phone?`<span class="lPh">📞 ${esc(clientRec(ledClient).phone)}</span>`:''}</div>
      <div class="lPeriod">${ledPeriod()}</div>
    </div>
    <div class="tw"><table class="sheet ledTbl">
      <thead><tr class="colHead"><th>#</th><th>التاريخ</th><th>البيان</th>
        <th>عليه (مدين)</th><th>له (دائن)</th><th>الرصيد</th><th class="noprint"></th></tr></thead>
      <tbody>${body||'<tr><td colspan="7" class="mut">ما في حركات بهالفترة</td></tr>'}
        <tr class="tot"><td colspan="3">المجموع</td>
          <td class="amt">${fx(deb)}</td><td class="amt">${fx(cre)}</td>
          <td class="amt">${fx(bal)}</td><td class="noprint"></td></tr>
        <tr class="net"><td colspan="5">${bal>=0?'الرصيد المستحق على':'الرصيد المستحق لـ'} ${esc(ledClient)}</td>
          <td class="amt">${fx(Math.abs(bal))}</td><td class="noprint"></td></tr>
      </tbody></table></div>
    <div class="ledFoot">
      <div>المبلغ بالكلمات: <b>${esc(numWords(Math.abs(bal)))}</b></div>
      <div class="sigRow"><span>توقيع المستلم: ..................</span>
        <span>${esc(settings.address||'')}${settings.phone?' · '+esc(settings.phone):''}</span></div>
    </div>
    <div class="row noprint" style="margin-top:12px">
      <button class="btn orange" onclick="ledExcel()">📊 تنزيل Excel</button>
      <button class="btn blue" onclick="window.print()">🖨️ طباعة / PDF</button>
    </div>
  </div>`;
}

/* تفقيط مبسّط للدنانير */
function numWords(n){
  n=Math.round((+n||0)*1000)/1000;
  const din=Math.floor(n), fils=Math.round((n-din)*1000);
  const ones=['','واحد','اثنان','ثلاثة','أربعة','خمسة','ستة','سبعة','ثمانية','تسعة','عشرة',
    'أحد عشر','اثنا عشر','ثلاثة عشر','أربعة عشر','خمسة عشر','ستة عشر','سبعة عشر','ثمانية عشر','تسعة عشر'];
  const tens=['','','عشرون','ثلاثون','أربعون','خمسون','ستون','سبعون','ثمانون','تسعون'];
  const huns=['','مئة','مئتان','ثلاثمئة','أربعمئة','خمسمئة','ستمئة','سبعمئة','ثمانمئة','تسعمئة'];
  const seg=x=>{
    if(x===0) return '';
    if(x<20) return ones[x];
    if(x<100){ const t=Math.floor(x/10),o=x%10; return o?ones[o]+' و'+tens[t]:tens[t]; }
    const h=Math.floor(x/100), r=x%100;
    return r?huns[h]+' و'+seg(r):huns[h];
  };
  const th=Math.floor(din/1000), rest=din%1000;
  let out='';
  if(th) out += (th===1?'ألف':th===2?'ألفان':seg(th)+' آلاف')+(rest?' و':'');
  if(rest||!th) out += seg(rest)||'صفر';
  let s=out+' دينار';
  if(fils) s+=' و'+seg(fils)+' فلس';
  return s+' فقط';
}

