function doParse(){
  const txt=$('raw').value.trim();
  if(!txt){toast('الصق الرسايل أولًا');return;}
  const r=parseText(txt,draft.day,draft.voucher,draft.date);
  if(!r.rows.length&&!r.skipped.length){toast('ما لقيت أي بند واضح');return;}
  draft.rows=draft.rows.concat(r.rows);
  draft.voucher=r.ctx.voucher; draft.date=r.ctx.date;
  if($('fVou'))$('fVou').value=draft.voucher;
  if($('fDate'))$('fDate').value=draft.date;
  lastSkipped=r.skipped;
  drawRows();
  toast(`تم قراءة ${r.rows.length} بند`);
}

/* ===== الصور ===== */
let IMG=null;   /* {url,w,h,kb} */

/* سحب وإفلات */
function dropImg(e){
  e.preventDefault();
  const dz=$('dropZone'); if(dz) dz.classList.remove('over');
  const f=[...(e.dataTransfer?.files||[])].find(x=>/^image\//.test(x.type));
  if(f) pickImg(f);
  else notify('ما لقيت صورة بالملف المسحوب','warn');
}

/* لصق بضغطة زر — بيقرأ من الحافظة مباشرة */
async function tryPaste(){
  try{
    if(!navigator.clipboard || !navigator.clipboard.read){
      notify('اضغط Ctrl+V للصق الصورة','warn',4000); return;
    }
    const items=await navigator.clipboard.read();
    for(const it of items){
      const type=it.types.find(t=>t.startsWith('image/'));
      if(type){
        const blob=await it.getType(type);
        pickImg(new File([blob],'pasted.png',{type}));
        return;
      }
    }
    notify('ما في صورة بالحافظة — انسخ صورة الأول','warn',4000);
  }catch(e){
    /* المتصفح بيرفض القراءة بدون إذن — Ctrl+V بيضل شغّال */
    notify('اضغط Ctrl+V للصق الصورة','warn',4000);
  }
}

function pickImg(f){
  if(!f) return;
  if(!/^image\//.test(f.type)){ notify('الملف مش صورة','warn'); return; }
  compressImg(f).then(o=>{ IMG=o; drawImg(); })
    .catch(()=>notify('ما قدرت أقرأ الصورة','bad'));
}

/* ضغط قبل الإرسال: يوفّر وقت ورفض من المزوّد */
function compressImg(file,maxSide=1600,q=0.82){
  return new Promise((res,rej)=>{
    const fr=new FileReader();
    fr.onerror=rej;
    fr.onload=()=>{
      const im=new Image();
      im.onerror=rej;
      im.onload=()=>{
        let {width:w,height:h}=im;
        const sc=Math.min(1,maxSide/Math.max(w,h));
        w=Math.round(w*sc); h=Math.round(h*sc);
        const c=document.createElement('canvas'); c.width=w; c.height=h;
        c.getContext('2d').drawImage(im,0,0,w,h);
        const url=c.toDataURL('image/jpeg',q);
        res({url,w,h,kb:Math.round(url.length*0.75/1024)});
      };
      im.src=fr.result;
    };
    fr.readAsDataURL(file);
  });
}

function drawImg(){
  const b=$('imgBox'); if(!b) return;
  if(!IMG){ b.innerHTML=''; return; }
  b.innerHTML=`<div class="imgPrev">
    <img src="${IMG.url}" alt="سند">
    <div>
      <div class="hint" style="margin:0 0 8px">${IMG.w}×${IMG.h} • ${IMG.kb}KB</div>
      <button class="btn orange" id="visBtn" onclick="doVision()">🔍 اقرأ الصورة</button>
      <button class="btn sec sm" onclick="IMG=null;drawImg()">إزالة</button>
    </div></div>`;
}

async function doVision(){
  if(!IMG){ notify('اختر صورة أولًا','warn'); return; }
  const k=(settings.ai.keys||{})[settings.ai.provider];
  if(!k){ notify('احفظ مفتاح API من الإعدادات أولًا','warn'); go('settings'); return; }
  const b=$('visBtn'), old=b.textContent;
  b.disabled=true; b.textContent='⏳ جاري قراءة الصورة…';
  try{
    const {data}=await aiVision(IMG.url);
    const vou=(data.voucher==='إدخال'||data.voucher==='إخراج')?data.voucher:draft.voucher;
    const rows=rowsFromAI(data,{day:draft.day,voucher:vou,date:draft.date, isVision:true});
    if(!rows.length) throw new Error('ما قدرت أقرأ أي بند من الصورة');
    draft.rows=draft.rows.concat(rows);
    draft.voucher=vou; if($('fVou'))$('fVou').value=vou;
    if(data.date&&/^\d{4}-\d{2}-\d{2}$/.test(data.date)){
      draft.date=data.date; if($('fDate'))$('fDate').value=data.date;
    }
    lastSkipped=[];
    drawRows();
    notify(`📷 قرأ ${rows.length} بند من الصورة — راجعهم منيح`,'ok',5000);
  }catch(e){
    const msg=String(e.message||e);
    if(/Failed to fetch|NetworkError|CORS/i.test(msg))
      say('تعذّر الاتصال','المتصفح منع الاتصال بالمزوّد أو ما في إنترنت.<br><br>جرّب مزوّد ثاني من الإعدادات.');
    else say('ما نجحت قراءة الصورة',esc(msg));
  }finally{ b.disabled=false; b.textContent=old; }
}

async function doAI(){
  const txt=$('raw').value.trim();
  if(!txt){toast('الصق الرسايل أولًا');return;}
  const k=(settings.ai.keys||{})[settings.ai.provider];
  if(!k){ toast('احفظ مفتاح API من تبويب الإعدادات أولًا'); go('settings'); return; }
  const b=$('aiBtn'), old=b.textContent;
  b.disabled=true; b.textContent='⏳ جاري التحليل...';
  try{
    const {data}=await aiAnalyze(txt,draft.day);
    const vou=(data.voucher==='إدخال'||data.voucher==='إخراج')?data.voucher:draft.voucher;
    const rows=rowsFromAI(data,{day:draft.day,voucher:vou,date:draft.date, isText:true});
    if(!rows.length) throw new Error('النموذج ما رجّع أي بند');
    draft.rows=draft.rows.concat(rows);
    if(data.voucher==='إدخال'||data.voucher==='إخراج'){
      draft.voucher=data.voucher; if($('fVou'))$('fVou').value=data.voucher;
    }
    lastSkipped=[];
    drawRows();
    toast(`🤖 حلّل ${rows.length} بند عبر ${AI_PROVIDERS[settings.ai.provider].label}`);
  }catch(e){
    const msg=String(e.message||e);
    if(/Failed to fetch|NetworkError|CORS/i.test(msg)){
      say('تعذّر الاتصال','المتصفح منع الاتصال بالمزوّد (CORS) أو ما في إنترنت.<br><br>'+
        'جرّب مزوّد ثاني من الإعدادات، أو استخدم زر «اقرأ الرسايل».');
    } else say('خطأ بالتحليل الذكي',esc(msg)+'<br><br>استخدم «اقرأ الرسايل» كبديل.');
  }finally{ b.disabled=false; b.textContent=old; }
}

